def gzip_bytes() -> bytes:
    raw = base64.b64decode(_DATA.encode("ascii"), validate=True)
    digest = hashlib.sha256(raw).hexdigest()
    if digest != EMBEDDED_HISTORY_SHA256:
        raise RuntimeError("El histórico Gatuno embebido está dañado")
    return raw

